# Auto-generated application assets for TTEmbed 2.0
import os
import sys
import tempfile
import base64
from PySide6.QtGui import QIcon, QPixmap

EMBEDDED_ICON_B64 = """"""
EMBEDDED_SPLASH_B64 = """"""

_CACHED_ICON_PATH = None
_CACHED_SPLASH_PATH = None

def get_icon_path() -> str:
    global _CACHED_ICON_PATH
    if _CACHED_ICON_PATH and os.path.exists(_CACHED_ICON_PATH):
        return _CACHED_ICON_PATH
    
    candidates = [
        os.path.join(os.path.dirname(__file__), "..", "assets", "ttembed.ico"),
        os.path.join(os.path.dirname(__file__), "ttembed.ico"),
        os.path.join(getattr(sys, "_MEIPASS", ""), "ttembed.ico"),
        "ttembed.ico"
    ]
    for c in candidates:
        if c and os.path.exists(c) and os.path.getsize(c) > 1000:
            _CACHED_ICON_PATH = c
            return _CACHED_ICON_PATH

    temp_path = os.path.join(tempfile.gettempdir(), "ttembed_2.0.ico")
    try:
        raw = base64.b64decode(EMBEDDED_ICON_B64)
        with open(temp_path, "wb") as f:
            f.write(raw)
        _CACHED_ICON_PATH = temp_path
        return _CACHED_ICON_PATH
    except Exception:
        return ""

def get_app_icon() -> QIcon:
    path = get_icon_path()
    if path and os.path.exists(path):
        return QIcon(path)
    return QIcon()

def get_splash_pixmap() -> QPixmap:
    global _CACHED_SPLASH_PATH
    candidates = [
        os.path.join(os.path.dirname(__file__), "..", "assets", "splash.png"),
        os.path.join(os.path.dirname(__file__), "splash.png"),
        os.path.join(getattr(sys, "_MEIPASS", ""), "splash.png"),
        "splash.png"
    ]
    for c in candidates:
        if c and os.path.exists(c):
            pix = QPixmap(c)
            if not pix.isNull():
                return pix

    try:
        raw = base64.b64decode(EMBEDDED_SPLASH_B64)
        pix = QPixmap()
        pix.loadFromData(raw, "PNG")
        return pix
    except Exception:
        return QPixmap(560, 340)

def apply_native_windows_icon(hwnd_int: int):
    path = get_icon_path()
    if not path or not os.path.exists(path):
        return
    try:
        import ctypes
        user32 = ctypes.windll.user32
        
        IMAGE_ICON = 1
        LR_LOADFROMFILE = 0x0010
        WM_SETICON = 0x0080
        ICON_SMALL = 0
        ICON_BIG = 1
        GCLP_HICON = -14
        GCLP_HICONSM = -34
        
        hicon_small = user32.LoadImageW(None, path, IMAGE_ICON, 16, 16, LR_LOADFROMFILE)
        hicon_big = user32.LoadImageW(None, path, IMAGE_ICON, 48, 48, LR_LOADFROMFILE)
        if not hicon_big:
            hicon_big = user32.LoadImageW(None, path, IMAGE_ICON, 32, 32, LR_LOADFROMFILE)
        
        if hicon_small:
            user32.SendMessageW(hwnd_int, WM_SETICON, ICON_SMALL, hicon_small)
            try:
                user32.SetClassLongPtrW(hwnd_int, GCLP_HICONSM, hicon_small)
            except Exception:
                pass
        if hicon_big:
            user32.SendMessageW(hwnd_int, WM_SETICON, ICON_BIG, hicon_big)
            try:
                user32.SetClassLongPtrW(hwnd_int, GCLP_HICON, hicon_big)
            except Exception:
                pass
    except Exception:
        pass
